#!/usr/bin/env python3
"""Chinna V6 standalone installer.

Run: python3 chinna_v6.py
This file is generated from the current repository sources.
"""
import base64
import json
import os
import shutil
import subprocess
import sys
import time
from pathlib import Path

VERSION = "6.0.0"
PORT = int(os.environ.get("CHINNA_DASHBOARD_PORT", "7777"))
HOME = Path.home()
CHINNA = Path(os.environ.get("CHINNA_HOME", str(HOME / ".chinna"))).expanduser()
FILES_B64 = "{\"bin/chinna\": \"\", \"lib/server.py\": \"\", \"dashboard/index.html\": \"\", \"lib/clean.sh\": \"\", \"lib/config.sh\": \"\", \"lib/daemon.sh\": \"\", \"lib/lang.sh\": \"\", \"lib/notify.sh\": \"\", \"lib/plugins.sh\": \"\", \"lib/registry.sh\": \"\", \"lib/server.sh\": \"\", \"lib/stack.sh\": \"\", \"lib/swiftbar.sh\": \"\", \"lib/voice.sh\": \"\", \"lib/plugins/_common.sh\": \"\", \"lib/plugins/app-control.sh\": \"\", \"lib/plugins/automation.sh\": \"\", \"lib/plugins/capture-clip.sh\": \"\", \"lib/plugins/deep-clean.sh\": \"\", \"lib/plugins/dev-runner.sh\": \"\", \"lib/plugins/focus-power.sh\": \"\", \"lib/plugins/git-tools.sh\": \"\", \"lib/plugins/godspeed-runner.sh\": \"\", \"lib/plugins/music-control.sh\": \"\", \"lib/plugins/network-toolkit.sh\": \"\", \"lib/plugins/node.sh\": \"\", \"lib/plugins/ports-network.sh\": \"\", \"lib/plugins/project-audit.sh\": \"\", \"lib/plugins/python.sh\": \"\", \"lib/plugins/quick-serve.sh\": \"\", \"lib/plugins/secure-chat.sh\": \"\", \"lib/plugins/storage-tools.sh\": \"\", \"lib/plugins/system-health.sh\": \"\", \"lib/plugins/whatsapp.sh\": \"\", \"whatsapp_bridge/package.json\": \"\", \"whatsapp_bridge/server.js\": \"\", \"extension/dist/manifest.json\": \"\", \"extension/dist/icon.svg\": \"\", \"extension/dist/background.js\": \"\", \"extension/dist/content.js\": \"\", \"extension/dist/popup.html\": \"\", \"extension/dist/sidepanel.html\": \"\", \"extension/dist/popup.css\": \"\", \"extension/dist/popup.js\": \"\"}"


def step(message):
    print(f"  -> {message}")


def ok(message):
    print(f"  OK {message}")


def write_file(rel, encoded):
    target = CHINNA / rel
    if rel == "bin/chinna":
        target = HOME / ".local" / "bin" / "chinna"
    if rel == "lib/server.py":
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(base64.b64decode(encoded))
        dashboard_server = CHINNA / "dashboard_server.py"
        dashboard_server.write_bytes(base64.b64decode(encoded))
        return target
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(base64.b64decode(encoded))
    if rel.endswith(".sh") or rel == "bin/chinna":
        target.chmod(0o755)
    return target


def stop_old_services():
    patterns = ["dashboard_server", "dashboard_server.py", "server.py 7777", "whatsapp_bridge/server.js"]
    for pattern in patterns:
        subprocess.run(["pkill", "-9", "-f", pattern], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def strict_cleanup():
    shutil.rmtree(CHINNA / "dashboard", ignore_errors=True)
    shutil.rmtree(CHINNA / "extension", ignore_errors=True)
    for path in [CHINNA / "dashboard_server.py", CHINNA / "lib" / "server.py", CHINNA / "server_v4.py", CHINNA / "install" / "chinna_v5.py"]:
        try:
            path.unlink()
        except FileNotFoundError:
            pass
    for cache_path in [HOME / "Library" / "Caches" / "com.chinna.Chinna", HOME / "Library" / "Saved Application State" / "com.chinna.Chinna.savedState"]:
        shutil.rmtree(cache_path, ignore_errors=True)
    if CHINNA.exists():
        for pyc in CHINNA.rglob("*.pyc"):
            try:
                pyc.unlink()
            except OSError:
                pass


def ensure_defaults():
    CHINNA.mkdir(parents=True, exist_ok=True)
    (CHINNA / "logs").mkdir(parents=True, exist_ok=True)
    (CHINNA / "VERSION").write_text(VERSION, encoding="utf-8")
    env_file = CHINNA / "env"
    if not env_file.exists():
        env_file.write_text("""# Chinna V6 Environment - never share this file
# OPENROUTER_API_KEY=
# ANTHROPIC_API_KEY=
# OPENAI_API_KEY=
APPAUTOMATIONMODE=off
APPNOTIFYSOUND=/System/Library/Sounds/Glass.aiff
APPNOTIFYSPEAK=off
CHINNA_DASHBOARD_PORT=7777
""", encoding="utf-8")
        env_file.chmod(0o600)
    models_file = CHINNA / "models"
    if not models_file.exists():
        models_file.write_text("""ACTIVE_MODEL="meta-llama/llama-3.3-70b-instruct:free"
MODEL_coder="openai/gpt-4o"
MODEL_reasoning="anthropic/claude-3.5-sonnet"
MODEL_small="openai/gpt-4o-mini"
MODEL_free="meta-llama/llama-3.3-70b-instruct:free"
MODEL_sonnet4="anthropic/claude-3.5-sonnet"
MODEL_opus4="anthropic/claude-3-opus"
MODEL_haiku4="anthropic/claude-3-haiku"
""", encoding="utf-8")
        models_file.chmod(0o600)


def start_server():
    log = (CHINNA / "dashboard.log").open("w")
    subprocess.Popen(["python3", str(CHINNA / "dashboard_server.py"), str(PORT)], stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
    time.sleep(3)


def main():
    print("Chinna V6 standalone installer")
    step("Stopping old services")
    stop_old_services()
    step("Clearing stale app code and caches")
    strict_cleanup()
    step("Writing fresh V6 files")
    for rel, encoded in json.loads(FILES_B64).items():
        write_file(rel, encoded)
    ensure_defaults()
    ok("Files installed")
    print(f"  Extension: {CHINNA / 'extension' / 'dist'}")
    step(f"Starting dashboard on port {PORT}")
    start_server()
    subprocess.run(["open", f"http://localhost:{PORT}"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    print()
    print(f"CHINNA V6 READY: http://localhost:{PORT}")
    print(f"Extension dist: {CHINNA / 'extension' / 'dist'}")
    print("Share command:")
    print('curl -fsSL -H "Cache-Control: no-cache" https://raw.githubusercontent.com/pichimail/chinna-go/main/install/install.sh | bash')


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        sys.exit(130)
